import React from "react";
import HorizontalButtonCard, { HorizontalButtonCardProps } from "../horizontalbuttonincard/HorizontalButtonCard";
import VerticalButtonCard, { VerticalButtonCardProps } from "../verticalbuttonincard/VerticalButtonCard";

export type ButtonCardProps = (HorizontalButtonCardProps & VerticalButtonCardProps) & {
  horizontal: boolean;
};

const ButtonCard: React.FC<ButtonCardProps> = ({ horizontal, ...props }) => {
  return horizontal ? (
    <HorizontalButtonCard {...props} />
  ) : (
    <VerticalButtonCard {...props} />
  );
};

export default ButtonCard;